"""Decide which files in a project tree are excluded by its .packignore files.

This is a pure-Python reimplementation of `packignore`, the legacy exclusion
engine. docs/PACKIGNORE.md describes the basics; the actual behaviour (which
this module reproduces exactly) differs from it in several ways:

Tree
  * Files are visited in `os.walk` order. A `.git` directory directly under
    the root is skipped, as are symlinks and anything that is not a regular
    file. Directories are only known through the files inside them.
  * Names are compared caselessly (Unicode case folding plus canonical
    normalization), as on a case-insensitive file system: when two paths
    collide, the name seen first is kept and the contents and mode of the
    one seen last win. A file colliding with a directory is an error.

.packignore syntax
  * Files are decoded as UTF-8 and split with `str.splitlines()`; each line is
    stripped of surrounding whitespace. Blank lines and lines starting with
    `;` are skipped (`#` is *not* a comment). A leading `!` negates the rest
    of the line. Backslash and `[` have no special meaning.
  * `*` and `?` match within one path segment; `**` as a whole segment matches
    any number of segments (including none); `**` elsewhere acts like `*`.
    `{a,b}` is an alternation running to the first following `}`; an
    unclosed `{` is literal.
  * Trailing `/`s make a pattern match directories only. Leading `/`s are
    dropped. A pattern still containing `/` is matched against the path
    relative to the .packignore's directory; otherwise against the base name.

Decision for a file
  * The file and each of its ancestor directories are tried deepest first.
    At the first level that any pattern matches, the winning pattern decides:
    the one from the deepest .packignore, then with the highest score (number
    of characters other than `*?/{},`), then the last one listed.
  * If no pattern matches the file itself, files with any executable bit set,
    or whose first line contains `@generated`, are excluded.
  * A .packignore only applies to paths strictly below its directory, and is
    not read at all when that directory is excluded.
"""

import os
import re
import stat
import unicodedata

_PACKIGNORE = ".packignore"
_NOT_SCORED = set("*?/{},")


class PackignoreError(Exception):
    """The tree cannot be evaluated (packignore reported an internal error)."""


class _Pattern:
    __slots__ = ("negated", "dir_only", "anchored", "regex", "score")

    def __init__(self, negated, dir_only, anchored, regex, score):
        self.negated = negated
        self.dir_only = dir_only
        self.anchored = anchored
        self.regex = regex
        self.score = score

    def matches(self, rel, is_dir):
        if self.dir_only and not is_dir:
            return False
        target = rel if self.anchored else rel.rsplit("/", 1)[-1]
        return self.regex.fullmatch(target) is not None


def _translate(pat, anchored):
    """Translate a glob into a regular expression string."""
    out = []
    i, n = 0, len(pat)
    group_end = -1  # index of the `}` closing the current alternation, if any
    while i < n:
        c = pat[i]
        if c == "*":
            j = i
            while j < n and pat[j] == "*":
                j += 1
            seg_start = i == 0 or pat[i - 1] == "/"
            seg_end = j == n or pat[j] == "/"
            if anchored and j - i == 2 and seg_start and seg_end:
                if i == 0 and j == n:
                    out.append(".*")
                elif j == n:
                    # "x/**": the slash before it was already emitted.
                    out.pop()
                    out.append("(?:/.*)?")
                else:
                    out.append("(?:.*/)?")
                    j += 1  # consume the following slash
            else:
                out.append("[^/]*")
            i = j
            continue
        if c == "?":
            out.append("[^/]")
        elif c == "{" and group_end < 0 and "}" in pat[i + 1:]:
            group_end = pat.index("}", i + 1)
            out.append("(?:")
        elif c == "}" and i == group_end:
            group_end = -1
            out.append(")")
        elif c == "," and group_end >= 0:
            out.append("|")
        else:
            out.append(re.escape(c))
        i += 1
    return "".join(out)


def _parse_line(line):
    line = line.strip()
    if not line or line.startswith(";"):
        return None
    negated = line.startswith("!")
    pat = line[1:] if negated else line
    score = sum(1 for c in pat if c not in _NOT_SCORED)
    dir_only = pat.endswith("/")
    pat = pat.rstrip("/").lstrip("/")
    if not pat:
        return None
    anchored = "/" in pat
    try:
        regex = re.compile(_translate(pat, anchored), re.DOTALL)
    except re.error:
        return None
    return _Pattern(negated, dir_only, anchored, regex, score)


def _parse(data):
    text = data.decode("utf-8")
    return [p for p in map(_parse_line, text.splitlines()) if p is not None]


def _fold(name):
    return unicodedata.normalize("NFD", unicodedata.normalize("NFD", name).casefold())


class _Dir:
    __slots__ = ("name", "dirs", "files")

    def __init__(self, name):
        self.name = name
        self.dirs = {}   # folded name -> _Dir
        self.files = {}  # folded name -> [name, full path, mode]


def _scan(root):
    """Build the caseless tree of regular files under `root`."""
    top = _Dir("")
    for dirpath, dirnames, filenames in os.walk(root):
        if os.path.samefile(dirpath, root) and ".git" in dirnames:
            dirnames.remove(".git")
        for name in filenames:
            full = os.path.join(dirpath, name)
            if os.path.islink(full) or not os.path.isfile(full):
                continue
            parts = os.path.relpath(full, root).replace(os.sep, "/").split("/")
            node = top
            for part in parts[:-1]:
                key = _fold(part)
                if key in node.files:
                    raise PackignoreError(f"{full}: file/directory name collision")
                node = node.dirs.setdefault(key, _Dir(part))
            key = _fold(parts[-1])
            if key in node.dirs:
                raise PackignoreError(f"{full}: file/directory name collision")
            mode = os.stat(full).st_mode
            if key in node.files:
                entry = node.files[key]
                entry[1], entry[2] = full, mode
            else:
                node.files[key] = [parts[-1], full, mode]
    return top


def _implicitly_ignored(full, mode):
    if mode & (stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH):
        return True
    with open(full, "rb") as f:
        first = b""
        while True:
            chunk = f.read(65536)
            if not chunk:
                break
            nl = chunk.find(b"\n")
            if nl >= 0:
                first += chunk[:nl]
                break
            first += chunk
            if b"@generated" in first[-65536 - 10:]:
                return True
    return b"@generated" in first


def _decide(parts, is_dir, rules):
    """Return True/False if a pattern decides `parts`, else None.

    `rules` lists (depth, patterns) for the .packignore files that apply,
    where depth is the number of path components of the directory holding
    the file. `parts` is the path (components) of the file or directory.
    """
    for level in range(len(parts), 0, -1):
        level_is_dir = is_dir or level < len(parts)
        best = None
        for depth, patterns in rules:
            if depth >= level:
                continue
            rel = "/".join(parts[depth:level])
            for idx, p in enumerate(patterns):
                if p.matches(rel, level_is_dir):
                    key = (depth, p.score, idx)
                    if best is None or key >= best[0]:
                        best = (key, p)
        if best is not None:
            return not best[1].negated
    return None


def ignored_files(root):
    """Return the files under `root` that its .packignore files exclude.

    Paths are relative to `root`, use "/" as the separator, and are sorted.
    Only files are listed, never directories. A `.git` directory directly
    under `root` is skipped.
    """
    result = []

    def visit(node, parts, rules):
        pi = next((e for e in node.files.values() if e[0] == _PACKIGNORE), None)
        if pi is not None:
            with open(pi[1], "rb") as f:
                rules = rules + [(len(parts), _parse(f.read()))]
        for name, full, mode in node.files.values():
            path = parts + [name]
            decision = _decide(path, False, rules)
            if decision is None:
                decision = _implicitly_ignored(full, mode)
            if decision:
                result.append("/".join(path))
        for child in node.dirs.values():
            path = parts + [child.name]
            if _decide(path, True, rules):
                # Excluded directory: its own .packignore is not read.
                walk_excluded(child, path, rules)
            else:
                visit(child, path, rules)

    def walk_excluded(node, parts, rules):
        # Everything below is evaluated with the inherited rules only; a
        # nested directory may still be re-included by them.
        visit_inner(node, parts, rules)

    def visit_inner(node, parts, rules):
        for name, full, mode in node.files.values():
            path = parts + [name]
            decision = _decide(path, False, rules)
            if decision is None:
                decision = _implicitly_ignored(full, mode)
            if decision:
                result.append("/".join(path))
        for child in node.dirs.values():
            path = parts + [child.name]
            if _decide(path, True, rules):
                visit_inner(child, path, rules)
            else:
                visit(child, path, rules)

    visit(_scan(root), [], [])
    return sorted(result)

