import importlib
import snapshot.ignore as IG

NAMES = ['a','b','A','B','ab','ba','abc','a.txt','b.py','x','X','d','D','.hidden','a b','{a}','a,b','!a',';a','#a','[a]','a*','é','e\u0301','ß','ss','build','tmp','.packignore']
PTOK = ['a','b','A','x','d','*','**','?','/','.','{','}',',','!','txt','py','[',']','\\',' ','ab','abc','é','#',';','-','e\u0301','ss','ß','build']

def rand_name(r):
    if r.random() < 0.7: return r.choice(NAMES)
    return ''.join(r.choice('abAB.xd{},') for _ in range(r.randint(1,3)))

def rand_pattern(r):
    k = r.random()
    if k < 0.15: return r.choice([';c','# c','','  ','!','/','**','*','!*','!**/','*/','!/'])
    s = ''.join(r.choice(PTOK) for _ in range(r.randint(1,5)))
    if r.random() < 0.3: s = '!' + s
    if r.random() < 0.1: s = ' ' + s + '\t'
    return s

def gen_tree(r, base):
    files = {}
    dirs = ['']
    nfiles = r.randint(1, 12)
    for _ in range(nfiles):
        parent = r.choice(dirs)
        if r.random() < 0.4 and parent.count('/') < 3:
            nd = (parent + '/' if parent else '') + rand_name(r)
            dirs.append(nd); parent = nd
        path = (parent + '/' if parent else '') + rand_name(r)
        files[path] = None
    # packignores
    for dd in dirs:
        if r.random() < 0.6:
            lines = [rand_pattern(r) for _ in range(r.randint(1,6))]
            files[(dd + '/' if dd else '') + '.packignore'] = '\n'.join(lines) + r.choice(['','\n','\r\n'])
    made = []
    for path, content in files.items():
        full = os.path.join(base, path)
        try:
            os.makedirs(os.path.dirname(full), exist_ok=True)
            if os.path.isdir(full): continue
            if content is None:
                c = r.random()
                content = '@generated\n' if c < 0.08 else ('x\n@generated' if c < 0.12 else 'data')
            with open(full, 'w') as f: f.write(content)
            if r.random() < 0.08: os.chmod(full, r.choice([0o755, 0o744, 0o654, 0o645]))
            made.append(path)
        except (FileExistsError, NotADirectoryError, IsADirectoryError):
            pass
    return made

def service(root):
    p = subprocess.run([sys.executable, '/work/repo/tools/packignore.orig', root], capture_output=True, text=True)
    if p.returncode: return 'ERR'
    return sorted(l for l in p.stdout.splitlines() if l)

def mine(root):
    try: return IG.ignored_files(root)
    except Exception as e: return 'ERR'

if __name__ == '__main__':
    seed0 = int(sys.argv[1]); n = int(sys.argv[2]); per = int(sys.argv[3]) if len(sys.argv) > 3 else 1
    bad = 0
    for s in range(seed0, seed0 + n):
        r = random.Random(s)
        root = tempfile.mkdtemp(dir='/tmp/p/trees')
        if per == 1:
            gen_tree(r, root)
        else:
            for i in range(per):
                os.makedirs(os.path.join(root, f't{i}'))
                gen_tree(r, os.path.join(root, f't{i}'))
        a, b = service(root), mine(root)
        if a != b:
            bad += 1
            print('SEED', s, 'per', per)
            if per > 1 and a != 'ERR' and b != 'ERR':
                sa, sb = set(a), set(b)
                print('  service-only', sorted(sa - sb)[:10]); print('  mine-only', sorted(sb - sa)[:10])
            else:
                print('  service', a if a == 'ERR' else len(a), 'mine', b if b == 'ERR' else len(b))
        shutil.rmtree(root)
    print('done, bad =', bad)
