import os
import re
import stat
import unicodedata

_PACKIGNORE = ".packignore"
_NOT_SCORED = set("*?/{},")


class PackignoreError(Exception):
    """The tree cannot be evaluated (packignore reported an internal error)."""


class _Pattern:
    __slots__ = ("negated", "dir_only", "anchored", "regex", "score")

    def __init__(self, negated, dir_only, anchored, regex, score):
        self.negated = negated
        self.dir_only = dir_only
        self.anchored = anchored
        self.regex = regex
        self.score = score

    def matches(self, rel, is_dir):
        if self.dir_only and not is_dir:
            return False
        target = rel if self.anchored else rel.rsplit("/", 1)[-1]
        return self.regex.fullmatch(target) is not None


def _expand_braces(pat):
    """Expand `{a,b}` groups; each runs from a `{` to the first `}` after it."""
    i = pat.find("{")
    j = pat.find("}", i + 1) if i >= 0 else -1
    if j < 0:
        return [pat]
    rest = _expand_braces(pat[j + 1:])
    return [pat[:i] + alt + r for alt in pat[i + 1:j].split(",") for r in rest]


def _translate_glob(pat, anchored):
    """Translate a brace-free glob into a regular expression string."""
    out = []
    i, n = 0, len(pat)
    while i < n:
        c = pat[i]
        if c == "*":
            j = i
            while j < n and pat[j] == "*":
                j += 1
            if (anchored and j - i == 2 and (i == 0 or pat[i - 1] == "/")
                    and (j == n or pat[j] == "/")):
                if j < n:
                    out.append("(?:.*/)?")
                    j += 1  # the slash is part of the optional group
                elif out and out[-1] == "/":
                    out[-1] = "(?:/.*)?"
                else:
                    out.append(".*")
            else:
                out.append("[^/]*")
            i = j
            continue
        out.append("[^/]" if c == "?" else re.escape(c))
        i += 1
    return "".join(out)


def _translate(pat, anchored):
    alts = [_translate_glob(alt, anchored) for alt in _expand_braces(pat)]
    return "(?:" + "|".join(alts) + ")"


def _parse_line(line):
    line = line.strip()
    if not line or line.startswith(";"):
        return None
    negated = line.startswith("!")
    pat = line[1:] if negated else line
    score = sum(1 for c in pat if c not in _NOT_SCORED)
    dir_only = pat.endswith("/")
    pat = pat.rstrip("/")
    anchored = "/" in pat
    pat = pat.lstrip("/")
    if not pat:
        return None
    try:
        regex = re.compile(_translate(pat, anchored), re.DOTALL)
    except re.error:
        return None
